    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    env = observation.get("environment_name", "resource_collection")
    # Defensive defaults for missing keys
    grid_width = observation.get("grid_width", 0)
    grid_height = observation.get("grid_height", 0)

    def move_towards(target_x, target_y):
        dx = 0
        dy = 0
        if target_x > sx:
            dx = 1
        elif target_x < sx:
            dx = -1
        if target_y > sy:
            dy = 1
        elif target_y < sy:
            dy = -1
        return [dx, dy]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            if ox != sx:
                dx = 1 if ox > sx else -1
                dy = 0
            elif oy != sy:
                dx = 0
                dy = 1 if oy > sy else -1
            else:
                dx, dy = 0, 0
            return [dx, dy]
        corners = [
            [0, 0],
            [0, grid_height - 1],
            [grid_width - 1, 0],
            [grid_width - 1, grid_height - 1],
        ]
        target = max(corners, key=lambda item: abs(item[0] - ox) + abs(item[1] - oy))
        return move_towards(target[0], target[1])
    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        if not targets:
            return [0, 0]
        target = min(targets, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
        return move_towards(target[0], target[1])
    resources = observation.get("resources") or []
    if resources:
        best = min(resources, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
        return move_towards(best[0], best[1])
    # Default move: approach opponent
    return move_towards(ox, oy)

